        "tema": "Social Copywriting",
        "objetivos": "Faço perguntas orientadas e conduzo exercícios em grupo para explorar frameworks relevantes e identificar práticas eficazes. Proponho desafios colaborativos para redesenhar conteúdos reais em tempo limitado, com foco nos objetivos. Incluo momentos de reflexão estruturada sobre as estratégias comunicacionais das marcas dos participantes e ajudo a encontrar formas de melhoria.\n\nUtilizo ferramentas digitais e templates visuais para facilitar a assimilação do conteúdo e permitir a aplicação imediata",
        "publico": "Profissionais de Marketing e Comunicação, Digital Marketers, Community Managers, Social Media Managers e todos os que pretendem aprender técnicas para criar narrativas nos canais de Social Media que inspirem, emocionem e impulsionem negócios, marcas e comunicação. Estudantes e recém-licenciados nas ",
