    "bio_curta": "Eduardo Marques Lopes é Diretor de Marketing e Comunicação do Clan desde 2019, no qual é também responsável pela oferta de serviços nas áreas de Employer Branding e Recruitment Marketing. É ainda formador nestas áreas na Lisbon Digital School e mentor de profissionais e empresas na Unicorn Factory L",
    "bio_completa": "Eduardo Marques Lopes é Diretor de Marketing e Comunicação do Clan desde 2019, no qual é também responsável pela oferta de serviços nas áreas de Employer Branding e Recruitment Marketing. É ainda formador nestas áreas na Lisbon Digital School e mentor de profissionais e empresas na Unicorn Factory Lisboa, no programa Nova SBE VOICE Leadership e na associação dNovo.\n\nNatural de Coimbra, Eduardo é licenciado em Economia pela Nova SBE e possui também um Mestrado Internacional em Gestão da Católica-Lisbon SBE. A nível profissional, o Eduardo iniciou a sua carreira na EY como Consultor e, em 2016, juntou-se à Winning Scientific Management, na qual assumia o cargo de Chief Operating Officer antes de integrar a equipa do Clan (anteriormente Multipessoal).",
