      {
        "tema": "Comunicação que transforma: pilares fundamentais",
        "objetivos": "Métodos e Técnicas Pedagógicas:\n• Exposição intercalada com interrogação.\n• Discussões orientadas em grupo.\n• Exercícios práticos com feedback imediato.\nRecursos Didáticos:\n• Projetor multimédia.\n• Guias práticos e fichas de exercícios.\n• Estudo de casos.\n• Discussões em grupo com moderação do formador.\n• Exercícios de role-playing para aplicação prática.\n• Exercícios de leitura em voz alta com ajustes vocais.\n• Role-playing com cenários simulados.",
        "publico": "Este curso é uma jornada transformadora para todos os que desejam dominar a arte da comunicação e influenciar eficazmente o seu público. Com um foco em desenvolver habilidades práticas identificando e dominando os princípios básicos da comunicação.",
        "duracao": "10h"
      }
