    "cursos": [
      {
        "tema": "UX Strategy",
        "objetivos": "A formação combina enquadramento teórico com forte componente prática, recorrendo a:\n        •        Exposição conceptual com exemplos reais\n        •        Análise de casos de estudo\n        •        Exercícios práticos de definição de visão, princípios e estratégia de UX\n        •        Trabalhos individuais e/ou em grupo para simulação de contextos organizacionais reais\n        •        Discussão orientada e feedback contínuo",
        "publico": "•UX Designers\n•Product Designers \n•Product e Project Managers\n•Profissionais de digital envolvidos em decisões estratégicas",
        "duracao": "12h"
      },
      {
        "tema": "UX Project Management",
        "objetivos": "A formação combina enquadramento teórico com forte componente prática, recorrendo a:\n        •        Enquadramento teórico sobre gestão de projetos aplicada a UX\n        •        Ferramentas práticas de planeamento e priorização\n        •        Simulações de projetos reais com restrições de tempo e recursos\n        •        Exercícios de definição de roadmap e planeamento de sprints\n        •        Discussão de erros comuns e boas práticas",
        "publico": "•        UX Designers e UX Researchers\n        •        Product Designers \n        •        Product e Project Managers\n•Profissionais de digital que trabalham em equipas multidisciplinares",
        "duracao": "12h"
      },
      {
        "tema": "Acessibilidade em UX Research",
        "objetivos": "A formação combina enquadramento teórico com forte componente prática, recorrendo a:\n        •        Enquadramento teórico baseado em normas e boas práticas (ex.: WCAG)\n        •        Análise de exemplos reais de research inclusivo\n        •        Exercícios práticos de adaptação de métodos de pesquisa\n        •        Discussão de casos e dilemas éticos em UX Research\n        •        Reflexão crítica sobre enviesamentos e exclusão em research",
        "publico": "•        UX Researchers\n        •        UX Designers e Product Designers\n        •        Profissionais de acessibilidade digital\n        •        Equipas de produto interessadas em inclusão e impacto social",
        "duracao": "6h"
      }
    ],
