        "objetivos": "O módulo combina metodologias participativas, aprendizagem baseada em desafios e aplicação prática de ferramentas de inovação sustentável.\n\nA sessão inicia-se com momentos de diálogo orientado, permitindo mapear o nível de maturidade dos participantes em sustentabilidade e inovação. Em seguida, são introduzidos conceitos estruturantes através de exemplos, dados e casos reais, promovendo pensamento crítico e sistêmico.\n\nA componente prática é central, com exercícios colaborativos baseados em ferr",
