        "tema": "Como Comunicar com Clareza",
        "objetivos": "Expositiva e participada com a aplicação de dinâmicas de grupo para análise e reflexão: - Exposição estruturada de conceitos com exemplos reais;\n- Discussão orientada e debate a partir de situações concretas;\n- Simulações e exercícios práticos de comunicação oral e escrita;\n- Roleplay de apresentações, reuniões e gestão de perguntas difíceis;\n- Sessões de reflexão guiada e feedback estruturado;\n- Aplicação a casos reais trazidos pelos participantes;\n- Utilização pontual de ferramentas digitais d",
        "publico": "First-Time Managers;\nMiddle Management\nTop Management / C-Level;\nPerfis técnicos com necessidade de reforço de competências de comunicação;\nLíderes em transição ou em funções de maior exposição;\nProfissionais seniores técnicos que necessitem de desenvolver competências de comunicação e presença prof",
        "duracao": "Sessão base: 6 horas (ajustável);\nSessão base + treino prático: 3 horas (ajustável);\nSessões de follow-up individuais ou em grupo: 1 hora (ajustável)"
