      {
        "tema": "Accessibilidade Digital na Prática para Developers",
        "objetivos": "Esta formação combina metodologias participativas, experienciais e de aplicação prática, com o objetivo de capacitar os participantes para identificar, compreender e corrigir problemas de acessibilidade em produtos digitais. Através de debates orientados por casos concretos e exercícios práticos, são explorados os princípios fundamentais da acessibilidade web, bem como boas práticas de HTML, CSS, ARIA e compatibilidade com tecnologias de apoio. A dimensão experiencial é reforçada por demonstraçõ",
        "publico": "Perfis Técnicos com necessidade de soft skills,\nProfissionais seniores técnicos / não gestores",
        "duracao": "Neste momento tem 12 horas, mas também poderia\najustar para ter mais horas se necessário."
      }
