    "cursos": [
      {
        "tema": "Product Owner",
        "objetivos": "Este curso tem uma abordagem muito prática àquilo que é a definição do perfil de Product Owner. Para além do conceito teórico, todas as turmas têm uma experiência hands on naquilo que é a definição de um produto. Isto permite que os grupos de trabalham consigam pensar de uma forma prática e estratégica naquilo que pode ser um produto. Ao mesmo tempo, procura entender quais são as suas valências de posicionamento de mercado, definição de ecossistema de atuação e as suas vantagens e riscos associa",
        "publico": "Recomendado para Product Owners, Program Managers, Project Managers, equipas técnicas de engenharia e design, managers da área da transformação digital ou inovação, Empreendedores e Intraempreendedores",
        "duracao": "Entre as 16h e as 20h"
      }
    ],
