    "cursos": [
      {
        "tema": "Fotografia Profissional",
        "objetivos": "Esta formação combina metodologias inspiracionais, participativas e práticas para desenvolver competências técnicas e criativas em fotografia. As sessões iniciam com momentos inspiracionais, onde são apresentados casos de referência e trabalhos premiados que desafiam os participantes a elevar a sua visão artística. Seguem-se debates orientados em torno de técnicas de iluminação, composição e direção fotográfica, incentivando a troca de experiências. A dimensão experiencial é trabalhada através d",
        "publico": "Criativos, Perfis Técnicos com necessidade de competências visuais, Estudantes e Profissionais em início de carreira na área da fotografia, bem como Gestores e Decisores que aprovam conteúdos fotográficos e precisam compreender critérios de qualidade.",
        "duracao": "A definir junto com a LDS"
      },
      {
        "tema": "Fotografia Profissional com AI",
        "objetivos": "A metodologia desta formação assenta numa combinação de prática fotográfica e exploração tecnológica. Os participantes começam por compreender workflows tradicionais de fotografia e depois experimentam ferramentas de Inteligência Artificial aplicadas à edição, retoque e criação de imagens. As sessões incluem demonstrações inspiracionais com exemplos de trabalhos híbridos (fotografia + AI) e debates orientados sobre as implicações artísticas e éticas desta integração. A dimensão experiencial é re",
        "publico": "Criativos, Profissionais de Fotografia e Comunicação, Empreendedores e Intraempreendedores que pretendem explorar AI em fluxos visuais, bem como Gestores e Decisores que aprovam conteúdos híbridos (fotografia + AI) e necessitam compreender o potencial e as limitações destas ferramentas.",
        "duracao": ""
      },
      {
        "tema": "Criar Conteúdos Fotográficos para Redes Sociais com AI",
        "objetivos": "Esta formação utiliza metodologias participativas e práticas, focadas na criação de conteúdos visuais para plataformas digitais. Os participantes criam casos reais de marcas (ou das marcas onde trabalham) para se destacar pelo impacto visual e debatem estratégias de adaptação de imagem a diferentes redes sociais (Instagram, TikTok, LinkedIn). A dimensão experiencial é potenciada por exercícios de produção e edição rápida, onde cada formando cria conteúdos fotográficos otimizados para social medi",
        "publico": "Profissionais de Marketing e Comunicação, Social Media Managers, Empreendedores e Intraempreendedores, Criativos e Decisores responsáveis pela aprovação de conteúdos digitais e campanhas visuais em redes sociais.",
        "duracao": ""
      },
      {
        "tema": "Posicionamento de Marca com Imagem e AI",
        "objetivos": "Esta formação assenta na análise estratégica do papel da imagem no posicionamento das marcas, partindo da premissa de que nenhuma marca comunica sem recorrer ao poder visual. Os participantes exploram como os arquétipos de marca moldam narrativas e influenciam perceções, aprendendo a construir mensagens consistentes através da fotografia e da estética visual. A metodologia combina momentos inspiracionais com estudos de caso nacionais e internacionais, onde se evidencia a forma como grandes marca",
        "publico": "Profissionais de Marketing, Brand Managers, Empreendedores e Intraempreendedores, Líderes em transição e Decisores estratégicos que aprovam campanhas visuais, com necessidade de compreender como a imagem influencia o posicionamento e a reputação da marca.",
        "duracao": ""
      },
      {
        "tema": "E-Commerce Visual: Fotografia e Imagem que Vendem com AI",
        "objetivos": "Esta formação centra-se em capacitar os participantes para compreenderem, em primeiro lugar, os princípios fundamentais da fotografia aplicada ao comércio eletrónico e as melhores práticas para criar imagens que realmente vendem, seja através da câmara ou com o apoio da Inteligência Artificial. Os formandos irão explorar como criar mundos visuais e cenários envolventes que reforçam o storytelling da marca e comunicam de forma poderosa a sua mensagem. A metodologia combina prática em estúdio e ex",
        "publico": "Empreendedores e Intraempreendedores, Profissionais de E-commerce e Marketing Digital, Criativos e Perfis Técnicos envolvidos na produção de catálogos online, bem como Gestores e Decisores que aprovam imagens e campanhas visuais orientadas para conversão.",
        "duracao": ""
      }
    ],
    "tab_categories": [
      "AI",
      "Ecommerce",
      "Social Media",
      "Vídeo & Imagem"
    ],
    "ativo": false
