    "bio_completa": "Vera Silva é jurtista e formadora especializada em Direito Digital, Proteção de Dados e Inteligência Artificial, com ampla experiência em formação e prática jurídica. É gestora na Lexicode Consulting, onde supervisiona a plataforma wescribe.pt, e tem colaborado com entidades como o IEFP, CESAE Digital e escolas de negócios no desenvolvimento de cursos e workshops sobre RGPD, legislação do e-commerce e regulamentação da IA. Oradora convidada em vários eventos, alia a prática jurídica à inovação tecnológica, apoiando marcas e organizações na adaptação a um ecossistema digital cada vez mais regulado.",
