        "objetivos": "> Exposição teórica com exemplos conceptuais e explicações claras._x000D_\n> Análise de casos e situações reais (sem ferramentas, sem execução técnica)._x000D_\n> Discussão orientada para a aplicação imediata em marcas, equipas ou projetos._x000D_\n> Estrutura modular e progressiva, que conduz o participante da estratégia ao planeamento._x000D_\n> Espaço para reflexão, alinhamento e clarificação de raciocínio estratégico.",
